row(22, 2, 'MATERIAL', f'IF YOUR BROTHER IS NOT NEAR YOU AND YOU KNOW HIM NOT, GATHER IT INTO YOUR HOUSE, AND IT STAYS WITH YOU UNTIL YOUR BROTHER SEEKS IT, AND YOU RETURN IT TO HIM. {HP(22, 2, (("עד", "דרש", "אחיך", "אתו"), "until your brother seeks it — 223:3\'s marks and the fraud"))} {AP(22, 2, (("עד", "דיתבע", "אחוך", "יתיה"), "UNTIL YOUR BROTHER CLAIMS IT — seek rendered claim (tava), the legal word"))} THE KEEPING until the claim. Fresh.')
row(22, 3, 'MATERIAL', f'SO SHALL YOU DO WITH HIS ASS, HIS GARMENT, EVERY LOST THING OF YOUR BROTHER\'S WHICH IS LOST FROM HIM AND YOU FOUND; YOU MAY NOT HIDE YOURSELF. {HP(22, 3, (("לכל", "אבדת", "אחיך"), "every lost thing of your brother — 224:5\'s widening"), (("לא", "תוכל", "להתעלם"), "you may not hide yourself"))} {AP(22, 3, (("לית", "לך", "רשו", "לאתכסאה"), "YOU HAVE NO PERMISSION TO HIDE YOURSELF — \'may not\' rendered \'no permission\' (reshu), the Aramaic\'s modal for the book\'s \'cannot\' (22:19, 22:29, 24:4)"))} Fresh.')
row(22, 4, 'MATERIAL', f'YOU SHALL NOT SEE YOUR BROTHER\'S ASS OR HIS OX FALLEN ON THE WAY AND HIDE YOURSELF; YOU SHALL SURELY RAISE WITH HIM. {HP(22, 4, (("נפלים", "בדרך"), "fallen on the way — 225:3-4\'s two conditions"), (("הקם", "תקים", "עמו"), "surely raise with him — 225:6\'s owner\'s part"))} {AP(22, 4, (("רמן", "בארחא"), "LYING ON THE ROAD"), (("אקמא", "תקים", "עמיה"), "surely raise with him"))} THE LOADING (222:3) beside Exodus 23:5\'s unloading. Fresh.')
row(22, 5, 'MATERIAL', f'NO MAN\'S GEAR SHALL BE ON A WOMAN, NOR SHALL A MAN WEAR A WOMAN\'S GARMENT, FOR AN ABOMINATION OF THE LORD YOUR GOD IS EVERYONE WHO DOES THESE. {HP(22, 5, (("לא", "יהיה", "כלי", "גבר", "על", "אשה"), "no man\'s gear on a woman"), (("כי", "תועבת", "יהוה", "אלהיך", "כל", "עשה", "אלה"), "for an abomination of the LORD your God is everyone who does these — the run of seven shared with 25:16"))} {AP(22, 5, (("לא", "יהי", "תקון", "זין", "דגבר", "על", "אתתא"), "NO ARMAMENT OF A MAN ON A WOMAN — the gear rendered weapons (R. Eliezer b. Jacob\'s reading, 226:2)"), (("ולא", "יתקן", "גבר", "בתקוני", "אתתא"), "nor shall a man ADORN himself with a woman\'s ADORNMENTS — the garment rendered ornaments (226:1\'s rule)"), (("ארי", "מרחק", "קדם", "יי"), "for it is DISTANCED before the LORD — the abomination formula\'s rendering, eleven seats"))} ONKELOS WRITES THE SIFREI\'S TWO RULES INTO THE VERSE; the Name\'s one seat in the chapter. Fresh.')
