row(22, 7, 'MATERIAL', f'SURELY SEND THE MOTHER AWAY AND TAKE THE YOUNG FOR YOURSELF, THAT IT MAY BE WELL WITH YOU AND YOUR DAYS LONG. {HP(22, 7, (("שלח", "תשלח", "את", "האם"), "surely send the mother — 228:1\'s positive commandment"), (("למען", "ייטב", "לך", "והארכת", "ימים"), "that it be well with you and your days long — the parents\' reward formula (5:16), 336:2\'s list"))} {AP(22, 7, (("בדיל", "דייטב", "לך", "ותוריך", "יומין"), "SO THAT IT BE WELL WITH YOU AND YOU PROLONG DAYS"))} THE REWARD CLAUSE on the cheapest commandment (228:8\'s a fortiori). Fresh.')
row(22, 8, 'MATERIAL', f'WHEN YOU BUILD A NEW HOUSE, MAKE A PARAPET FOR YOUR ROOF, AND PUT NOT BLOOD IN YOUR HOUSE WHEN THE FALLER FALLS FROM IT. {HP(22, 8, (("כי", "תבנה", "בית", "חדש"), "when you build a new house — 20:5\'s phrase, 229:1"), (("ולא", "תשים", "דמים", "בביתך"), "and put not blood in your house — 229:2-4\'s widening"), (("כי", "יפל", "הנפל", "ממנו"), "when the faller falls from it — 229:7-8"))} {AP(22, 8, (("ותעבד", "תיקא", "לאגרך"), "AND MAKE A FENCE FOR YOUR ROOF"), (("ולא", "תשוי", "חובת", "דין", "דקטול", "בביתך"), "AND PUT NOT THE LIABILITY OF A DEATH SENTENCE IN YOUR HOUSE — \'blood\' rendered as the court\'s liability (the phrase again at 22:26)"))} ONKELOS MAKES THE BLOOD A LIABILITY — the parapet\'s omission a capital guilt in the Aramaic. Fresh.')
row(22, 9, 'MATERIAL', f'SOW NOT YOUR VINEYARD WITH MIXED SEED, LEST THE FULLNESS OF THE SEED YOU SOW AND THE PRODUCE OF THE VINEYARD BE SANCTIFIED. {HP(22, 9, (("לא", "תזרע", "כרמך", "כלאים"), "sow not your vineyard with mixed seed — 230:1\'s second prohibition"), (("פן", "תקדש", "המלאה", "הזרע"), "lest the fullness of the seed be sanctified — 230:3-4, 230:12"))} {AP(22, 9, (("לא", "תזרע", "כרמך", "ערובין"), "SOW NOT YOUR VINEYARD WITH MIXTURES"), (("דילמא", "תסתאב", "דמעת", "זרעא"), "LEST THE FULLNESS OF THE SEED BE DEFILED — \'sanctified\' rendered \'defiled\' (tistaav): the forbidden as the unclean, R. Josiah\'s \'lest it be forbidden\' (230:12) in the Aramaic\'s word"))} Fresh.')
row(22, 10, 'MATERIAL', f'PLOW NOT WITH AN OX AND AN ASS TOGETHER. {HP(22, 10, (("לא", "תחרש", "בשור", "ובחמר", "יחדו"), "plow not with an ox and an ass together — 231:1\'s pair, 230:10\'s each alone"))} {AP(22, 10, (("לא", "תרדי", "בתורא", "ובחמרא", "כחדא"), "PLOW NOT WITH THE OX AND THE ASS AS ONE"))} the five-word verse with no kin in the Bible (the ink\'s find 12). Fresh.')
