row(22, 19, 'MATERIAL', f'AND FINE HIM A HUNDRED OF SILVER AND GIVE TO THE GIRL\'S FATHER, FOR HE BROUGHT AN EVIL NAME ON A VIRGIN OF ISRAEL; AND SHE SHALL BE HIS WIFE — HE MAY NOT SEND HER AWAY ALL HIS DAYS. {HP(22, 19, (("וענשו", "אתו", "מאה", "כסף"), "and fine him a hundred of silver — 238:3-4 money, Tyrian"), (("ונתנו", "לאבי", "הנערה"), "and give to the girl\'s father — THE GIRL WRITTEN IN FULL, the one seat of twelve"), (("לא", "יוכל", "לשלחה", "כל", "ימיו"), "he may not send her away all his days — with the lamed; 22:29 without it"))} {AP(22, 19, (("ויגבון", "מניה", "מאה", "סלעין", "דכסף"), "AND THEY EXACT FROM HIM A HUNDRED SELA OF SILVER — the coin named"), (("לית", "ליה", "רשו", "למפטרה", "כל", "יומוהי"), "HE HAS NO PERMISSION TO RELEASE HER ALL HIS DAYS — \'send away\' rendered release (patar — the bill\'s root, 24:1\'s get piturin)"))} Fresh.')
