row(22, 21, 'MATERIAL', f'THEY BRING THE GIRL OUT TO THE DOOR OF HER FATHER\'S HOUSE, AND THE MEN OF HER CITY STONE HER WITH STONES AND SHE DIES, FOR SHE DID FOLLY IN ISRAEL TO PLAY THE HARLOT IN HER FATHER\'S HOUSE; AND YOU PURGE THE EVIL FROM YOUR MIDST. {HP(22, 21, (("אל", "פתח", "בית", "אביה"), "to the door of her father\'s house — 239:3, 235:6\'s place"), (("כי", "עשתה", "נבלה", "בישראל"), "for she did folly in Israel — Achan\'s and Jeremiah\'s phrase"), (("ובערת", "הרע", "מקרבך"), "and purge the evil from your midst — the formula\'s sixth seat"))} {AP(22, 21, (("ארי", "עבדת", "קלנא", "בישראל"), "FOR SHE DID A DISGRACE IN ISRAEL (kelana)"), (("ותפלי", "עבד", "דביש", "מבינך"), "AND REMOVE THE DOER OF EVIL FROM AMONG YOU — the formula as a person, 240:5\'s reading"))} Fresh.')
