row(22, 24, 'MATERIAL', f'YOU BRING BOTH OF THEM OUT TO THE GATE OF THAT CITY AND STONE THEM WITH STONES AND THEY DIE — THE GIRL BECAUSE SHE DID NOT CRY OUT IN THE CITY, AND THE MAN BECAUSE HE HUMBLED HIS NEIGHBOR\'S WIFE; AND YOU PURGE THE EVIL FROM YOUR MIDST. {HP(22, 24, (("והוצאתם", "את", "שניהם", "אל", "שער", "העיר", "ההוא"), "you bring both out to the gate of that city — 242:4\'s gate where found; the plural \'you\' the chapter\'s one"), (("על", "דבר", "אשר", "לא", "צעקה", "בעיר"), "because she did not cry out in the city — 242:6\'s warning"), (("אשר", "ענה", "את", "אשת", "רעהו"), "he humbled his neighbor\'s wife — the betrothed already a wife"))} {AP(22, 24, (("על", "עסק", "די", "לא", "צוחת", "בקרתא"), "ON THE MATTER THAT SHE DID NOT CRY OUT IN THE CITY (esak)"), (("דעני", "ית", "אתת", "חבריה"), "that he humbled his fellow\'s wife"))} Fresh.')
