row(22, 26, 'MATERIAL', f'AND TO THE GIRL DO NOTHING; THE GIRL HAS NO SIN WORTHY OF DEATH, FOR AS A MAN RISES AGAINST HIS NEIGHBOR AND MURDERS HIM, SO IS THIS THING. {HP(22, 26, (("ולנער", "לא", "תעשה", "דבר"), "and to the girl do nothing — the girl written twice as a boy (the store two tokens more)"), (("אין", "לנער", "חטא", "מות"), "the girl has no sin worthy of death — 243:1\'s three exemptions"), (("כאשר", "יקום", "איש", "על", "רעהו", "ורצחו", "נפש"), "as a man rises against his neighbor and murders him — 243:2\'s pursuer"))} {AP(22, 26, (("לית", "לעולמתא", "חובת", "דין", "דקטול"), "THE GIRL HAS NO LIABILITY OF A DEATH SENTENCE — 22:8\'s phrase for \'blood\', the chapter\'s second seat"), (("כן", "פתגמא", "הדין"), "so is this word"))} THE ARAMAIC\'S ONE PHRASE FOR THE PARAPET\'S BLOOD AND THE GIRL\'S SIN. Fresh.')
