row(22, 28, 'MATERIAL', f'IF A MAN FINDS A VIRGIN GIRL WHO IS NOT BETROTHED AND SEIZES HER AND LIES WITH HER, AND THEY ARE FOUND. {HP(22, 28, (("נער", "בתולה", "אשר", "לא", "ארשה"), "a virgin girl who is not betrothed — Exodus 22:15\'s run of four; 244:1\'s three a fortiori"), (("ותפשה", "ושכב", "עמה", "ונמצאו"), "and seizes her and lies with her and they are found — 244:3 by witnesses"))} {AP(22, 28, (("ויחדנה", "וישכוב", "עמה", "וישתכחון"), "AND SEIZES HER AND LIES WITH HER AND THEY ARE FOUND"))} THE RAPIST beside Exodus\'s seducer. Fresh.')
row(22, 29, 'MATERIAL', f'THE MAN WHO LAY WITH HER GIVES THE GIRL\'S FATHER FIFTY OF SILVER, AND SHE SHALL BE HIS WIFE BECAUSE HE HUMBLED HER; HE MAY NOT SEND HER AWAY ALL HIS DAYS. {HP(22, 29, (("לאבי", "הנער", "חמשים", "כסף"), "to the girl\'s father fifty of silver — 245:2-4"), (("ולו", "תהיה", "לאשה", "תחת", "אשר", "ענה"), "and she shall be his wife because he humbled her — 22:19\'s run of three; 245:5-6"), (("לא", "יוכל", "שלחה", "כל", "ימיו"), "he may not send her away all his days — without the lamed, 22:19\'s twin close"))} {AP(22, 29, (("חמשין", "סלעין", "דכסף"), "FIFTY SELA OF SILVER"), (("חלף", "די", "עניה"), "in exchange that he humbled her"), (("לית", "ליה", "רשו", "למפטרה", "כל", "יומוהי"), "HE HAS NO PERMISSION TO RELEASE HER ALL HIS DAYS — 22:19\'s clause word for word"))} the chapter\'s close; the levir the one release (245:7). Fresh.')
